'use client';

import { useState } from 'react';
import { SiteHeader } from "@/components/shared/site-header";
import { Hero } from "@/components/landing/hero";
import { Experience } from "@/components/landing/experience";
import { Projects } from "@/components/landing/projects";
import { Skills } from "@/components/landing/skills";
import { Education } from "@/components/landing/education";
import { Contact } from "@/components/landing/contact";
import { Footer } from "@/components/landing/footer";
import Galaxy from "@/components/shared/galaxy";
import { Intro } from "@/components/landing/intro";

export default function Home() {
  const [showIntro, setShowIntro] = useState(true);

  return (
    <div className="min-h-screen bg-black">
      {/* 
        Structure:
        .page.under (z-index: 10) - The Site Content
        canvas/galaxy (z-index: 1) - The Galaxy Background (fixed)
        .page (z-index: 100) - The Intro Layer (fixed overlay)
      */}
      
      {/* Revealed Site Layer */}
      <div className="page under">
        <SiteHeader />
        <main className="flex-1">
          <Hero />
          <Experience />
          <Projects />
          <Skills />
          <Education />
          <Contact />
        </main>
        <Footer />
      </div>

      {/* WebGL Background Layer */}
      <div className="fixed inset-0 z-[1] pointer-events-none overflow-hidden">
        <Galaxy 
          mouseRepulsion
          mouseInteraction
          density={1}
          glowIntensity={0.3}
          saturation={0}
          hueShift={140}
          twinkleIntensity={0.3}
          rotationSpeed={0.1}
          repulsionStrength={2}
          autoCenterRepulsion={0}
          starSpeed={0.5}
          speed={1}
        />
      </div>

      {/* Intro Overlay Layer */}
      {showIntro && (
        <div className="page fixed inset-0 z-[100]">
          <Intro onFinish={() => setShowIntro(false)} />
        </div>
      )}
    </div>
  );
}
