import Image from 'next/image';
import { projects } from '@/lib/data';
import { PlaceHolderImages } from '@/lib/placeholder-images';
import { Section } from './section';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { CodeXml } from 'lucide-react';

export function Projects() {
  return (
    <Section id="projects" title="Projects">
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {projects.map((project, index) => {
          const placeholder = PlaceHolderImages.find(p => p.id === project.imageId);
          return (
            <Card key={index} className="flex flex-col overflow-hidden hover:shadow-primary/10 transition-all duration-300 hover:-translate-y-2 animate-in fade-in slide-in-from-bottom-5" style={{animationDelay: `${index * 150}ms`}}>
              {placeholder && (
                <div className="aspect-video relative">
                  <Image
                    src={placeholder.imageUrl}
                    alt={project.title}
                    fill
                    className="object-cover"
                    data-ai-hint={placeholder.imageHint}
                  />
                </div>
              )}
              <CardHeader>
                <div className="flex items-center gap-4">
                  <div className="bg-primary/10 p-2 rounded-full text-primary">
                    <CodeXml className="h-5 w-5" />
                  </div>
                  <CardTitle>{project.title}</CardTitle>
                </div>
              </CardHeader>
              <CardContent className="flex-grow flex flex-col">
                <CardDescription className="flex-grow">{project.description}</CardDescription>
                <div className="mt-4 flex flex-wrap gap-2">
                  {project.tags.map((tag, i) => (
                    <Badge key={i} variant="secondary">{tag}</Badge>
                  ))}
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </Section>
  );
}
